AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    /* Check if PM detection has already completed for this flow */
    if (!FlowAppLayerIsPMDetectCompleted(f, direction)) {
        AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        FlowAppLayerSetPMDetectCompleted(f, direction);
    }

    /* Get protocol from PM detection */
    alproto = FlowAppLayerGetPMDetectResult(f, direction);

    /* If PM detection didn't find anything, try PP detection */
    if (alproto == ALPROTO_UNKNOWN) {
        AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        alproto = FlowAppLayerGetPPDetectResult(f, direction);
    }

    /* Check for DCERPC protocol to avoid misclassification */
    if (alproto == ALPROTO_DCERPC) {
        if (direction == APP_LAYER_TO_SERVER && f->dce_rpc != NULL) {
            if (!DCE2RPCStreamCheckForPipe(f->dce_rpc)) {
                alproto = ALPROTO_UNKNOWN;
            }
        }
    }

    /* Check expectation list for detection if still unknown */
    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProto(f)) {
        alproto = AppLayerProtoDetectDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            FlowSetAppProto(f, alproto);
        } else {
            AppProto tmp = AppLayerProtoDetectDetectPP(tctx, f, buf, buflen, ipproto, direction);
            if (tmp != ALPROTO_UNKNOWN && tmp != ALPROTO_CONTINUE) {
                alproto = tmp;
                FlowSetAppProto(f, alproto);
            } else {
                AppProto expected = AppLayerProtoDetectExpectationList(f, ipproto, direction);
                if (expected != ALPROTO_UNKNOWN) {
                    alproto = expected;
                    FlowSetAppProto(f, alproto);
                }
            }
        }
    } else {
        alproto = FlowGetAppProto(f);
    }

    if (alproto == ALPROTO_DCERPC) {
        if (AppLayerProtoDetectCheckDCERPCMisclass(buf, buflen)) {
            alproto = ALPROTO_UNKNOWN;
            FlowSetAppProto(f, alproto);
        }
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProto(f)) {
        if (AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction, &alproto) == 1)
            return alproto;
    }

    if (alproto == ALPROTO_UNKNOWN) {
        if (AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction, &alproto) == 1)
            return alproto;
    }

    if (alproto == ALPROTO_UNKNOWN) {
        if (AppLayerProtoDetectExpectation(tctx, f, &alproto) == 1)
            return alproto;
    }

    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowPMInspectionDone(f, direction)) {
        AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction, &alproto);
        if (alproto != ALPROTO_UNKNOWN) {
            FlowSetAppProto(f, alproto);
            return alproto;
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction, &alproto);
        if (alproto != ALPROTO_UNKNOWN) {
            FlowSetAppProto(f, alproto);
            return alproto;
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        AppLayerProtoDetectExpectationList(tctx, f, ipproto, &alproto);
        if (alproto != ALPROTO_UNKNOWN) {
            FlowSetAppProto(f, alproto);
            return alproto;
        }
    }

    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowPMStateCompleted(f, direction)) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN)
            goto detect_done;
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN)
            goto detect_done;
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    }

detect_done:
    if (alproto == ALPROTO_DCERPC) {
        if (FlowGetAppProto(f, direction) == ALPROTO_SMB)
            alproto = ALPROTO_SMB;
    }

    return alproto;
}
